/**
 * US-21 — build_alert.
 *
 * Formats ONE actionable alert from the n8n Error Trigger payload: workflow,
 * execution id, failing node, error message (truncated, single line) and the
 * execution URL. Never includes credentials, RUT, addresses or recipe contents:
 * the Error Trigger payload carries workflow metadata only.
 * When TELEGRAM_ADMIN_CHAT_ID is missing the item is dropped (executions stay
 * in the n8n list) — the runbook explains the fallback.
 */
function truncateText(value, max) {
  const text = String(value === null || value === undefined ? '' : value);
  if (text.length <= max) return text;
  return text.slice(0, max - 3) + '...';
}

function collapseWhitespace(value) {
  return String(value === null || value === undefined ? '' : value)
    .replace(/\s+/g, ' ')
    .trim();
}

function buildErrorAlert(input) {
  const source = input && typeof input === 'object' ? input : {};
  const wf = source.workflow && typeof source.workflow === 'object' ? source.workflow : {};
  const ex = source.execution && typeof source.execution === 'object' ? source.execution : {};
  const rawError = ex.error;
  const err = rawError && typeof rawError === 'object' ? rawError : {};
  const name = wf.name ? String(wf.name) : 'workflow desconocido';
  const execId = ex.id !== undefined && ex.id !== null ? String(ex.id) : 'sin id';
  let node = '';
  if (err.node && typeof err.node === 'object' && err.node.name) node = String(err.node.name);
  else if (typeof err.node === 'string') node = err.node;
  else if (err.nodeName) node = String(err.nodeName);
  const message = truncateText(
    collapseWhitespace(typeof rawError === 'string' ? rawError : err.message || 'sin mensaje'),
    300
  );
  let text = 'ALERTA n8n: el workflow "' + name + '" falló (ejecución ' + execId + ').';
  if (node) text += ' Nodo: ' + node + '.';
  text += ' Error: ' + message + '.';
  if (ex.url) text += ' Revisar: ' + collapseWhitespace(ex.url) + '.';
  return text;
}

function buildAlertItem(input, adminChatId) {
  const chat = adminChatId === null || adminChatId === undefined ? '' : String(adminChatId).trim();
  if (chat === '') return null;
  return { chat_id: chat, severity: 'CRITICAL', message: buildErrorAlert(input) };
}

// --- n8n data assembly (guarded so the test harness can load the functions) ---
if (typeof $input !== 'undefined') {
  const items = $input.all();
  const out = [];
  for (let i = 0; i < items.length; i++) {
    const json = items[i] && items[i].json ? items[i].json : items[i];
    const item = buildAlertItem(json, process.env.TELEGRAM_ADMIN_CHAT_ID);
    if (item) out.push({ json: item });
  }
  return out;
}
